```json
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {"AWS": "arn:aws:iam::CENTRAL_ACCOUNT_ID:role/BackupWriter"},
      "Action": "sts:AssumeRole"
    }
  ]
}
```

